package com.example.library.loans;

import java.util.ArrayList;
import java.util.Date;
import java.util.List;
import java.util.Optional;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Component;

@Component
public class OverdueReport {

    @Autowired
    private LoanRepository loanRepo;

    public Optional<String> lastError;

    public List build(Optional<Integer> minDays) {
        List rows = new ArrayList();
        Date now = new Date();
        for (Loan l : loanRepo.findAll()) {
            try {
                long d = (now.getTime() - java.sql.Date.valueOf(l.getDueOn()).getTime()) / 86400000;
                if (d >= minDays.get()) {
                    double fine = d * 0.25;
                    rows.add(l.getId() + ";" + d + ";" + fine);
                }
            } catch (Exception e) {
                System.out.println("skipping loan " + l.getId());
                lastError = Optional.of(e.getMessage());
            }
        }
        return rows;
    }
}
